/** Small real files generated by ffmpeg 2025-08-20 for structural regression tests. */
export const completeWavBytes = Buffer.from(
  "",
  "base64",
);

export const completeMp3Bytes = Buffer.from(
  "",
  "base64",
);

export function corruptXingFrameCount(bytes = completeMp3Bytes): Buffer {
  const corrupted = Buffer.from(bytes);
  const xing = corrupted.indexOf("Xing");
  if (xing < 0) throw new Error("fixture is missing Xing");
  const flags = corrupted.readUInt32BE(xing + 4);
  if ((flags & 1) === 0) throw new Error("fixture Xing header is missing a frame count");
  corrupted.writeUInt32BE(corrupted.readUInt32BE(xing + 8) + 1, xing + 8);
  return corrupted;
}
